using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    public DbSet<DiscountedProduct> DiscountedProducts => Set<DiscountedProduct>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfApp");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses "$type" instead of
        // "Discriminator" for the discriminator property by default.
        // For existing documents that already store "Discriminator", you must explicitly
        // configure the old property name to avoid breaking reads.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Product>("Product")
            .HasValue<DiscountedProduct>("DiscountedProduct");

        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public decimal Price { get; set; }
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported by the
    // Cosmos DB provider. All queries must use async methods (ToListAsync, etc.).
    // The sync methods (ToList, First, Single, etc.) will throw
    // InvalidOperationException at runtime.

    // BEFORE (broken in EF Core 9):
    // List<Product> GetProducts(CosmosDbContext db) =>
    //     db.Products.Where(p => p.Price > 10).ToList();

    // AFTER (fixed — use async):
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db) =>
        await db.Products.Where(p => p.Price > 10).ToListAsync();

    async Task<Product?> GetProductAsync(CosmosDbContext db, string name) =>
        await db.Products.FirstOrDefaultAsync(p => p.Name == name);
}

