using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported by the
    // Cosmos DB provider. All queries must use async methods (ToListAsync, etc.).
    // The sync methods (ToList, First, Single, etc.) will throw
    // InvalidOperationException at runtime.

    // BEFORE (broken in EF Core 9):
    // List<Product> GetProducts(CosmosDbContext db) =>
    //     db.Products.Where(p => p.Price > 10).ToList();

    // AFTER (fixed — use async):
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db) =>
        await db.Products.Where(p => p.Price > 10).ToListAsync();

    async Task<Product?> GetProductAsync(CosmosDbContext db, string name) =>
        await db.Products.FirstOrDefaultAsync(p => p.Name == name);
}
